// One documentation page per registered locale (/locales/<code>/), generated by
// brand/tools/gen_locale_pages.py from spec/locales/*.json and promo/locale-examples.json.
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const PROMO_DIR = path.join(ROOT, "promo");

type Source = { rule: string; cite: string; url?: string };
type LocaleFile = { locale: string; name: string; sources: Source[] };

const registered = JSON.parse(
  readFileSync(path.join(ROOT, "spec/locales/registry.json"), "utf8"),
) as {
  locales: string[];
};
const examples = JSON.parse(readFileSync(path.join(PROMO_DIR, "locale-examples.json"), "utf8")) as {
  locales: Record<string, { byRule: Record<string, unknown[]>; disagreed: number }>;
};
// A locale newer than the installed engine has no examples and no page until the engine knows it.
const registry = { locales: registered.locales.filter((code) => code in examples.locales) };

function page(code: string): string {
  const p = path.join(PROMO_DIR, "locales", code, "index.html");
  if (!existsSync(p)) throw new Error(`${p} missing — run "npm run gen:docs" first`);
  return readFileSync(p, "utf8");
}

describe("locale pages", () => {
  it("every registry locale the installed engine can exemplify has a page, and no other has one", () => {
    expect(registry.locales.length).toBeGreaterThanOrEqual(19);
    for (const code of registry.locales)
      expect(existsSync(path.join(PROMO_DIR, "locales", code, "index.html"))).toBe(true);
    for (const code of registered.locales.filter((c) => !registry.locales.includes(c)))
      expect(existsSync(path.join(PROMO_DIR, "locales", code, "index.html"))).toBe(false);
  });

  it("the locales index links every locale page", () => {
    const index = readFileSync(path.join(PROMO_DIR, "locales", "index.html"), "utf8");
    for (const code of registry.locales) {
      const links = index.split(`href="${"../"}locales/${code}/"`).length - 1;
      expect(links, code).toBeGreaterThanOrEqual(2); // card and coverage-table row
    }
  });

  it("sitemap and llms.txt list every locale page", () => {
    const sitemap = readFileSync(path.join(PROMO_DIR, "sitemap.xml"), "utf8");
    const llms = readFileSync(path.join(PROMO_DIR, "llms.txt"), "utf8");
    for (const code of registry.locales) {
      expect(sitemap).toContain(`<loc>https://polytypo.dev/locales/${code}/</loc>`);
      expect(llms).toContain(`https://polytypo.dev/locales/${code}/`);
    }
  });

  for (const code of registry.locales) {
    describe(`locales/${code}`, () => {
      const html = page(code);
      const locale = JSON.parse(
        readFileSync(path.join(ROOT, "spec/locales", `${code}.json`), "utf8"),
      ) as LocaleFile;

      it("has its own canonical URL, TechArticle and breadcrumbs", () => {
        expect(html).toContain(
          `<link rel="canonical" href="https://polytypo.dev/locales/${code}/">`,
        );
        expect(html).toMatch(/"@type": "TechArticle"/);
        expect(html).toMatch(/"@type": "BreadcrumbList"/);
        expect(html).toContain(`"item": "https://polytypo.dev/locales/"`);
      });

      it("references assets at its real depth and marks itself current", () => {
        expect(html).toContain('href="../../assets/style.css"');
        expect(html).toContain(`<a href="../../locales/${code}/" aria-current="page">`);
      });

      it("renders every citation of the locale file in its Sources section", () => {
        const sources = html.slice(html.indexOf('id="sources"'));
        const items = sources.match(/<li><span lang="/g) ?? [];
        expect(items).toHaveLength(locale.sources.length);
        for (const s of locale.sources) {
          if (s.url) expect(sources).toContain(`href="${s.url.replace(/&/g, "&amp;")}"`);
        }
      });

      it("shows worked examples run through the engine", () => {
        const entry = examples.locales[code]!;
        const cases = Object.values(entry.byRule).flat();
        expect(cases.length).toBeGreaterThan(0);
        expect(entry.disagreed).toBe(0);
        expect(html).toContain('id="quotes"');
        expect(html).toContain('id="modes"');
      });

      it("has no unresolved template tokens and no duplicate heading ids", () => {
        expect(html).not.toMatch(/\{\{[^}]+\}\}/);
        const ids = [...html.matchAll(/<h[2-4] id="([^"]+)"/g)].map((m) => m[1]);
        expect(new Set(ids).size).toBe(ids.length);
      });

      it("promises no unshipped work and uses no banned wording", () => {
        const text = html.replace(/<script[\s\S]*?<\/script>/g, "");
        expect(text).not.toMatch(
          /coming soon|roadmap|we plan|planned|will be supported|microtypography/i,
        );
      });
    });
  }

  it("titles and H1s are unique, lead with the locale and carry the query words", () => {
    const titles = registry.locales.map((c) => page(c).match(/<title>([^<]*)<\/title>/)?.[1]);
    expect(new Set(titles).size).toBe(titles.length);
    for (const t of titles) expect(t).toMatch(/ typography rules: .* \| polytypo$/);
    const h1s = registry.locales.map((c) => page(c).match(/<h1>(.*?)<\/h1>/)?.[1]);
    expect(new Set(h1s).size).toBe(h1s.length);
  });

  it("each page carries the native name, a quick answer, a playground link and 3-level breadcrumbs", () => {
    const natives = JSON.parse(
      readFileSync(path.join(ROOT, "brand/tools/locale_native_names.json"), "utf8"),
    ) as Record<string, string>;
    for (const code of registry.locales) {
      const html = page(code);
      expect(natives[code], code).toBeTruthy();
      expect(html).toContain(natives[code]!);
      expect(html).toContain('<p class="doc-lead">');
      expect(html).toContain(`href="../../playground/?locale=${code}">full playground`);
      expect(html).toContain('id="pg-demo"');
      expect(html.match(/"@type": "ListItem"/g)).toHaveLength(3);
      expect(html).toContain('"inLanguage": "en"');
    }
  });

  it("descriptions are unique across locale pages", () => {
    const d = registry.locales.map(
      (c) => page(c).match(/<meta name="description" content="([^"]*)">/)?.[1],
    );
    expect(new Set(d).size).toBe(d.length);
  });
});
